    { const char * tb_v390 = "// «переменные потока» — настоящие: у каждой задачи свой блок, на него смотрит регистр FS\n"; *(const char * *)tb_grow(v_lines) = tb_v390; }
    { const char * tb_v391 = "// (так их не надо копировать при смене задачи, и на нескольких ядрах процессора у каждого свои)\n"; *(const char * *)tb_grow(v_lines) = tb_v391; }
    { const char * tb_v392 = "#define _Thread_local __thread __attribute__((tls_model(\"local-exec\")))\n"; *(const char * *)tb_grow(v_lines) = tb_v392; }
    { const char * tb_v393 = "#define EOF (-1)\n"; *(const char * *)tb_grow(v_lines) = tb_v393; }
