    { const char * tb_v408 = "TB_INL void tb_outl(unsigned short port, unsigned int v) { __asm__ volatile(\"outl %0, %1\" : : \"a\"(v), \"Nd\"(port)); }\n"; *(const char * *)tb_grow(v_lines) = tb_v408; }
