    { const char * tb_v452 = "    else if (ch == '\\b') { if (tb_vcol > 0) tb_vcol--; tb_vga[tb_vrow * 80 + tb_vcol] = (unsigned short)(tb_vcolor << 8 | ' '); }\n"; *(const char * *)tb_grow(v_lines) = tb_v452; }
