    { const char * tb_v915 = "        if (c < 0) hi = mid; else lo = mid + 1;\n"; *(const char * *)tb_grow(v_lines) = tb_v915; }
    { const char * tb_v916 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v916; }
