    { const char * tb_v985 = "    int *locks[8]; int nlocks;            // замки, которые клетка держит сейчас\n"; *(const char * *)tb_grow(v_lines) = tb_v985; }
    { const char * tb_v986 = "    int svc;                              // служба (a = service f()): ей можно в запас памяти\n"; *(const char * *)tb_grow(v_lines) = tb_v986; }
    { const char * tb_v987 = "    int soft;                             // сейчас new_mem / grow_mem: нет памяти — ошибка, а не падение\n"; *(const char * *)tb_grow(v_lines) = tb_v987; }
    { const char * tb_v988 = "    unsigned char tls[TB_TLS_MAX + 16] __attribute__((aligned(16)));   // блок переменных потока + адрес самого себя\n"; *(const char * *)tb_grow(v_lines) = tb_v988; }
    { const char * tb_v989 = "} tb_kslot;\n"; *(const char * *)tb_grow(v_lines) = tb_v989; }
