    { const char * tb_v1024 = "// new_mem / grow_mem просят память «мягко»: не хватило — ответ else err, клетка живёт\n"; *(const char * *)tb_grow(v_lines) = tb_v1024; }
    { const char * tb_v1025 = "TB_API int tb_mem_soft_now(void) { return !tb_in_irq && tb_slots[tb_cur].soft > 0; }\n"; *(const char * *)tb_grow(v_lines) = tb_v1025; }
    { const char * tb_v1026 = "TB_API void tb_mem_soft(int d) { if (!tb_in_irq) tb_slots[tb_cur].soft += d; }\n"; *(const char * *)tb_grow(v_lines) = tb_v1026; }
    { const char * tb_v1027 = "TB_API size_t tb_heap_limit(void) {\n"; *(const char * *)tb_grow(v_lines) = tb_v1027; }
    { const char * tb_v1028 = "    if (tb_in_irq || tb_cur == 0 || tb_slots[tb_cur].svc) return TB_HEAP;\n"; *(const char * *)tb_grow(v_lines) = tb_v1028; }
