    { const char * tb_v3567 = "// ---------- background: работа в своём потоке ----------\n"; *(const char * *)tb_grow(v_lines) = tb_v3567; }
    { const char * tb_v3568 = "#ifndef TB_BARE\n"; *(const char * *)tb_grow(v_lines) = tb_v3568; }
    { const char * tb_v3569 = "typedef struct { pthread_t th; int done; void *res; } tb_task;\n"; *(const char * *)tb_grow(v_lines) = tb_v3569; }
    { const char * tb_v3570 = "TB_API void tb_task_start(tb_task *t, void *(*run)(void *), void *arg) {\n"; *(const char * *)tb_grow(v_lines) = tb_v3570; }
    { const char * tb_v3571 = "    t->done = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v3571; }
