    { const char * tb_v3573 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v3573; }
    { const char * tb_v3574 = "// a = service f(): в программе с ОС служба — тот же background (запас памяти есть только в ядре)\n"; *(const char * *)tb_grow(v_lines) = tb_v3574; }
    { const char * tb_v3575 = "TB_API void tb_service_start(tb_task *t, void *(*run)(void *), void *arg) { tb_task_start(t, run, arg); }\n"; *(const char * *)tb_grow(v_lines) = tb_v3575; }
    { const char * tb_v3576 = "// a.wait: дождаться потока (один раз) и отдать адрес ответа\n"; *(const char * *)tb_grow(v_lines) = tb_v3576; }
    { const char * tb_v3577 = "TB_API void *tb_wait(tb_task *t) {\n"; *(const char * *)tb_grow(v_lines) = tb_v3577; }
    { const char * tb_v3578 = "    if (!t->done) { pthread_join(t->th, 0); t->done = 1; }\n"; *(const char * *)tb_grow(v_lines) = tb_v3578; }
    { const char * tb_v3579 = "    return t->res;\n"; *(const char * *)tb_grow(v_lines) = tb_v3579; }
    { const char * tb_v3580 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v3580; }
    { const char * tb_v3581 = "// a.crashed: в обычной программе падение задачи роняет всю программу — сюда доходят только целые\n"; *(const char * *)tb_grow(v_lines) = tb_v3581; }
    { const char * tb_v3582 = "TB_API _Bool tb_crashed(tb_task *t) { tb_wait(t); return 0; }\n"; *(const char * *)tb_grow(v_lines) = tb_v3582; }
    { const char * tb_v3583 = "#endif\n"; *(const char * *)tb_grow(v_lines) = tb_v3583; }
    { const char * tb_v3584 = "TB_API int tb_dhas(tb_dict *d, const void *k) { return tb_dfind(d, k) >= 0; }\n"; *(const char * *)tb_grow(v_lines) = tb_v3584; }
    { const char * tb_v3585 = "TB_API void tb_dremove(tb_dict *d, const void *k) {\n"; *(const char * *)tb_grow(v_lines) = tb_v3585; }
    { const char * tb_v3586 = "    long long at = tb_dfind(d, k);\n"; *(const char * *)tb_grow(v_lines) = tb_v3586; }
    { const char * tb_v3587 = "    if (at < 0) return;\n"; *(const char * *)tb_grow(v_lines) = tb_v3587; }
    { const char * tb_v3588 = "    if (d->mode != 0) tb_dto_hash(d);\n"; *(const char * *)tb_grow(v_lines) = tb_v3588; }
    { const char * tb_v3589 = "    long long last = d->keys->len - 1;\n"; *(const char * *)tb_grow(v_lines) = tb_v3589; }
    { const char * tb_v3590 = "    // на место удалённого ставим последний: порядок меняется только у него\n"; *(const char * *)tb_grow(v_lines) = tb_v3590; }
    { const char * tb_v3591 = "    memcpy(d->keys->data + at * d->keys->size, d->keys->data + last * d->keys->size, d->keys->size);\n"; *(const char * *)tb_grow(v_lines) = tb_v3591; }
    { const char * tb_v3592 = "    memcpy(d->vals->data + at * d->vals->size, d->vals->data + last * d->vals->size, d->vals->size);\n"; *(const char * *)tb_grow(v_lines) = tb_v3592; }
    { const char * tb_v3593 = "    d->keys->len -= 1;\n"; *(const char * *)tb_grow(v_lines) = tb_v3593; }
    { const char * tb_v3594 = "    d->vals->len -= 1;\n"; *(const char * *)tb_grow(v_lines) = tb_v3594; }
    { const char * tb_v3595 = "    tb_dreindex(d, d->nslots);\n"; *(const char * *)tb_grow(v_lines) = tb_v3595; }
    { const char * tb_v3596 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v3596; }
    { const char * tb_v3597 = "TB_API tb_dict *tb_dict_from(int text, long long vsize, long long n, const void *keys, const void *vals) {\n"; *(const char * *)tb_grow(v_lines) = tb_v3597; }
    { const char * tb_v3598 = "    tb_dict *d = tb_dict_new(text, vsize);\n"; *(const char * *)tb_grow(v_lines) = tb_v3598; }
    { const char * tb_v3599 = "    long long ksize = d->keys->size;\n"; *(const char * *)tb_grow(v_lines) = tb_v3599; }
    { const char * tb_v3600 = "    for (long long i = 0; i < n; i++) {\n"; *(const char * *)tb_grow(v_lines) = tb_v3600; }
    { const char * tb_v3601 = "        memcpy(tb_dput(d, (const char *)keys + i * ksize, 0), (const char *)vals + i * vsize, vsize);\n"; *(const char * *)tb_grow(v_lines) = tb_v3601; }
    { const char * tb_v3602 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v3602; }
