    { const char * tb_v4017 = "TB_API long long tb_syscall(long long n, long long a, long long b, long long c, long long d, long long e, long long f, int line) {\n"; *(const char * *)tb_grow(v_lines) = tb_v4017; }
    { const char * tb_v4018 = "    (void)line;\n"; *(const char * *)tb_grow(v_lines) = tb_v4018; }
