    { const char * tb_v4021 = "    return (long long)r;\n"; *(const char * *)tb_grow(v_lines) = tb_v4021; }
    { const char * tb_v4022 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v4022; }
    { const char * tb_v4023 = "#ifdef __APPLE__\n"; *(const char * *)tb_grow(v_lines) = tb_v4023; }
