    { const char * tb_v5533 = "    return u;\n"; *(const char * *)tb_grow(v_lines) = tb_v5533; }
    { const char * tb_v5534 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v5534; }
    { const char * tb_v5535 = "TB_API long long tb_text_width(long long fi, const char *s, long long size) {\n"; *(const char * *)tb_grow(v_lines) = tb_v5535; }
    { const char * tb_v5536 = "    if (fi < 0 || fi >= tb_nfonts || size <= 0) return 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v5536; }
