    { const char * tb_v5539 = "    const unsigned char *p = (const unsigned char *)s;\n"; *(const char * *)tb_grow(v_lines) = tb_v5539; }
    { const char * tb_v5540 = "    while (*p) {\n"; *(const char * *)tb_grow(v_lines) = tb_v5540; }
    { const char * tb_v5541 = "        unsigned u = tb_utf8_next(&p);\n"; *(const char * *)tb_grow(v_lines) = tb_v5541; }
    { const char * tb_v5542 = "        if (u == '\\n') { if (pen > best) best = pen; pen = 0; continue; }\n"; *(const char * *)tb_grow(v_lines) = tb_v5542; }
    { const char * tb_v5543 = "        pen += tb_ttf_adv(f, tb_ttf_glyph(f, u)) * scale;\n"; *(const char * *)tb_grow(v_lines) = tb_v5543; }
    { const char * tb_v5544 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v5544; }
