    { const char * tb_v5547 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v5547; }
    { const char * tb_v5548 = "TB_API void tb_draw_image_a(long long id, long long x, long long y);\n"; *(const char * *)tb_grow(v_lines) = tb_v5548; }
