    { const char * tb_v5577 = "TB_API tb_ginst *tb_gi = 0;            // память экземпляров (видна видеокарте)\n"; *(const char * *)tb_grow(v_lines) = tb_v5577; }
    { const char * tb_v5578 = "TB_API int tb_gin = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v5578; }
    { const char * tb_v5579 = "// 3D: глубина. У треугольника сетки своя «плоскость глубины» A, B, C (целые числа, см. tb_tri3_depth);\n"; *(const char * *)tb_grow(v_lines) = tb_v5579; }
