    { const char * tb_v5679 = "        tb_gpu_add(x0, y0, x1, y1, cx, cy, (uint32_t)c & 0xFFFFFF, (1u << 30) | (uint32_t)r);\n"; *(const char * *)tb_grow(v_lines) = tb_v5679; }
    { const char * tb_v5680 = "        return;\n"; *(const char * *)tb_grow(v_lines) = tb_v5680; }
