    { const char * tb_v5685 = "        long long rest = r * r + r - j * j, i = (long long)sqrt((double)rest);\n"; *(const char * *)tb_grow(v_lines) = tb_v5685; }
    { const char * tb_v5686 = "        while (i * i > rest) i--;\n"; *(const char * *)tb_grow(v_lines) = tb_v5686; }
