    { const char * tb_v7290 = "// --- мышь PS/2: пакеты по 3 байта (по 4 — с колёсиком) ---\n"; *(const char * *)tb_grow(v_lines) = tb_v7290; }
    { const char * tb_v7291 = "TB_API unsigned char tb_mpk[4];\n"; *(const char * *)tb_grow(v_lines) = tb_v7291; }
    { const char * tb_v7292 = "TB_API int tb_mpn = 0, tb_mpsize = 3;\n"; *(const char * *)tb_grow(v_lines) = tb_v7292; }
    { const char * tb_v7293 = "TB_API void tb_ps2_wait_in(void) { for (int i = 0; i < 100000 && (tb_inb(0x64) & 2); i++) {} }\n"; *(const char * *)tb_grow(v_lines) = tb_v7293; }
    { const char * tb_v7294 = "TB_API int tb_ps2_read(void) {\n"; *(const char * *)tb_grow(v_lines) = tb_v7294; }
    { const char * tb_v7295 = "    for (int i = 0; i < 100000; i++) if (tb_inb(0x64) & 1) return tb_inb(0x60);\n"; *(const char * *)tb_grow(v_lines) = tb_v7295; }
    { const char * tb_v7296 = "    return -1;\n"; *(const char * *)tb_grow(v_lines) = tb_v7296; }
