    { const char * tb_v7298 = "TB_API int tb_mouse_cmd(unsigned char c) {\n"; *(const char * *)tb_grow(v_lines) = tb_v7298; }
    { const char * tb_v7299 = "    tb_ps2_wait_in(); tb_outb(0x64, 0xD4);\n"; *(const char * *)tb_grow(v_lines) = tb_v7299; }
    { const char * tb_v7300 = "    tb_ps2_wait_in(); tb_outb(0x60, c);\n"; *(const char * *)tb_grow(v_lines) = tb_v7300; }
