    { const char * tb_v7302 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v7302; }
    { const char * tb_v7303 = "// «мышь виртуальной машины» (vmmouse в QEMU и VMware): точное место курсора, а не сдвиги —\n"; *(const char * *)tb_grow(v_lines) = tb_v7303; }
    { const char * tb_v7304 = "// мышь не надо «ловить» в окне QEMU. Есть — берём её, нет — обычные пакеты PS/2\n"; *(const char * *)tb_grow(v_lines) = tb_v7304; }
    { const char * tb_v7305 = "TB_API int tb_vmm = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v7305; }
    { const char * tb_v7306 = "TB_API void tb_vmm_call(uint32_t cmd, uint32_t arg, uint32_t r[4]) {\n"; *(const char * *)tb_grow(v_lines) = tb_v7306; }
    { const char * tb_v7307 = "    uint32_t a = 0x564D5868u, b = arg, c = cmd, d = 0x5658;\n"; *(const char * *)tb_grow(v_lines) = tb_v7307; }
    { const char * tb_v7308 = "    __asm__ volatile(\"inl %%dx, %%eax\" : \"+a\"(a), \"+b\"(b), \"+c\"(c), \"+d\"(d) : : \"memory\");\n"; *(const char * *)tb_grow(v_lines) = tb_v7308; }
    { const char * tb_v7309 = "    r[0] = a; r[1] = b; r[2] = c; r[3] = d;\n"; *(const char * *)tb_grow(v_lines) = tb_v7309; }
    { const char * tb_v7310 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v7310; }
    { const char * tb_v7311 = "TB_API void tb_vmm_init(void) {\n"; *(const char * *)tb_grow(v_lines) = tb_v7311; }
