    { const char * tb_v7313 = "    tb_vmm_call(10, 0, r);                               // «кто здесь»: в ответе ebx — тот же магический номер\n"; *(const char * *)tb_grow(v_lines) = tb_v7313; }
    { const char * tb_v7314 = "    if (r[1] != 0x564D5868u) return;\n"; *(const char * *)tb_grow(v_lines) = tb_v7314; }
    { const char * tb_v7315 = "    tb_vmm_call(41, 0x45414552u, r);                     // включить\n"; *(const char * *)tb_grow(v_lines) = tb_v7315; }
    { const char * tb_v7316 = "    tb_vmm_call(40, 0, r);\n"; *(const char * *)tb_grow(v_lines) = tb_v7316; }
    { const char * tb_v7317 = "    if (r[0] == 0xFFFF0000u || (r[0] & 0xFFFF) == 0) return;\n"; *(const char * *)tb_grow(v_lines) = tb_v7317; }
    { const char * tb_v7318 = "    tb_vmm_call(39, 1, r);\n"; *(const char * *)tb_grow(v_lines) = tb_v7318; }
    { const char * tb_v7319 = "    if (r[0] != 0x3442554Au) return;\n"; *(const char * *)tb_grow(v_lines) = tb_v7319; }
    { const char * tb_v7320 = "    tb_vmm_call(41, 0x53424152u, r);                     // точные координаты\n"; *(const char * *)tb_grow(v_lines) = tb_v7320; }
    { const char * tb_v7321 = "    tb_vmm = 1;\n"; *(const char * *)tb_grow(v_lines) = tb_v7321; }
    { const char * tb_v7322 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v7322; }
    { const char * tb_v7323 = "TB_API void tb_vmm_read(void) {\n"; *(const char * *)tb_grow(v_lines) = tb_v7323; }
    { const char * tb_v7324 = "    uint32_t r[4];\n"; *(const char * *)tb_grow(v_lines) = tb_v7324; }
    { const char * tb_v7325 = "    for (;;) {\n"; *(const char * *)tb_grow(v_lines) = tb_v7325; }
    { const char * tb_v7326 = "        tb_vmm_call(40, 0, r);\n"; *(const char * *)tb_grow(v_lines) = tb_v7326; }
