    { const char * tb_v7338 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v7338; }
    { const char * tb_v7339 = "TB_API void tb_mouse_irq(void) {\n"; *(const char * *)tb_grow(v_lines) = tb_v7339; }
    { const char * tb_v7340 = "    unsigned char st = tb_inb(0x64);\n"; *(const char * *)tb_grow(v_lines) = tb_v7340; }
    { const char * tb_v7341 = "    if (!(st & 1)) return;\n"; *(const char * *)tb_grow(v_lines) = tb_v7341; }
