    { const char * tb_v7350 = "    if (tb_mpk[0] & 0xC0) dx = dy = 0;            // переполнение: пакет не верен\n"; *(const char * *)tb_grow(v_lines) = tb_v7350; }
    { const char * tb_v7351 = "    tb_mx += dx; tb_my -= dy;\n"; *(const char * *)tb_grow(v_lines) = tb_v7351; }
    { const char * tb_v7352 = "    if (tb_mx < 0) tb_mx = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v7352; }
    { const char * tb_v7353 = "    if (tb_my < 0) tb_my = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v7353; }
    { const char * tb_v7354 = "    if (tb_mx >= tb_gw) tb_mx = tb_gw - 1;\n"; *(const char * *)tb_grow(v_lines) = tb_v7354; }
