    { const char * tb_v7356 = "    int down = tb_mpk[0] & 1;\n"; *(const char * *)tb_grow(v_lines) = tb_v7356; }
    { const char * tb_v7357 = "    if (down && !tb_mdown) tb_mtap = 1;\n"; *(const char * *)tb_grow(v_lines) = tb_v7357; }
    { const char * tb_v7358 = "    tb_mdown = down;\n"; *(const char * *)tb_grow(v_lines) = tb_v7358; }
    { const char * tb_v7359 = "    if (tb_mpsize == 4) {\n"; *(const char * *)tb_grow(v_lines) = tb_v7359; }
