    { const char * tb_v7377 = "    tb_mouse_cmd(0xF3); tb_mouse_cmd(200); tb_mouse_cmd(0xF3); tb_mouse_cmd(100); tb_mouse_cmd(0xF3); tb_mouse_cmd(80);\n"; *(const char * *)tb_grow(v_lines) = tb_v7377; }
    { const char * tb_v7378 = "    if (tb_mouse_cmd(0xF2) == 0xFA && tb_ps2_read() == 3) tb_mpsize = 4;\n"; *(const char * *)tb_grow(v_lines) = tb_v7378; }
    { const char * tb_v7379 = "    tb_mouse_cmd(0xF4);                            // слать движения\n"; *(const char * *)tb_grow(v_lines) = tb_v7379; }
