    { const char * tb_v8276 = "    if (s >= XK_a && s <= XK_z) return 'A' + (int)(s - XK_a);\n"; *(const char * *)tb_grow(v_lines) = tb_v8276; }
    { const char * tb_v8277 = "    if (s >= XK_A && s <= XK_Z) return 'A' + (int)(s - XK_A);\n"; *(const char * *)tb_grow(v_lines) = tb_v8277; }
