    { const char * tb_v8390 = "#endif\n"; *(const char * *)tb_grow(v_lines) = tb_v8390; }
    { const char * tb_v8391 = "// TB_GPU_CHECK: проба смешивания. Видеокарты считают смешивание по-своему (AMD на Mac — с малой\n"; *(const char * *)tb_grow(v_lines) = tb_v8391; }
    { const char * tb_v8392 = "// точностью, ошибка зависит и от цвета буквы, и от фона), поэтому проба берёт все сочетания:\n"; *(const char * *)tb_grow(v_lines) = tb_v8392; }
    { const char * tb_v8393 = "// цвет c, фон d, прозрачность a — 256 × 256 × 256 точек, кадр за кадром, и процессор дальше\n"; *(const char * *)tb_grow(v_lines) = tb_v8393; }
    { const char * tb_v8394 = "// смешивает по этой таблице (tb_blend_lut[c][d][a]). Делается один раз, когда есть и окно, и шрифт.\n"; *(const char * *)tb_grow(v_lines) = tb_v8394; }
    { const char * tb_v8395 = "// После пробы кадр видеокарты снова становится таким же, как у процессора (копия tb_px)\n"; *(const char * *)tb_grow(v_lines) = tb_v8395; }
    { const char * tb_v8396 = "TB_API void tb_gpu_blend_probe(void) {\n"; *(const char * *)tb_grow(v_lines) = tb_v8396; }
    { const char * tb_v8397 = "    if (!tb_gpu_on || !tb_gpu_check || tb_blend_cal || !tb_px || !tb_nfonts) return;\n"; *(const char * *)tb_grow(v_lines) = tb_v8397; }
    { const char * tb_v8398 = "    uint8_t *lut = malloc((size_t)1 << 24);\n"; *(const char * *)tb_grow(v_lines) = tb_v8398; }
    { const char * tb_v8399 = "    if (!lut) return;\n"; *(const char * *)tb_grow(v_lines) = tb_v8399; }
    { const char * tb_v8400 = "    size_t n = (size_t)tb_gw * tb_gh, p0 = tb_imgpx_n, need = p0 + 3 * n;\n"; *(const char * *)tb_grow(v_lines) = tb_v8400; }
    { const char * tb_v8401 = "    int n0 = tb_nimg;\n"; *(const char * *)tb_grow(v_lines) = tb_v8401; }
    { const char * tb_v8402 = "    uint32_t *all = need <= 0xFFFFFFFFu ? realloc(tb_imgpx, need * 4) : 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v8402; }
    { const char * tb_v8403 = "    tb_image *list = realloc(tb_imgs, (size_t)(n0 + 3) * sizeof(tb_image));\n"; *(const char * *)tb_grow(v_lines) = tb_v8403; }
    { const char * tb_v8404 = "    if (all) tb_imgpx = all;\n"; *(const char * *)tb_grow(v_lines) = tb_v8404; }
    { const char * tb_v8405 = "    if (list) tb_imgs = list;\n"; *(const char * *)tb_grow(v_lines) = tb_v8405; }
    { const char * tb_v8406 = "    if (!all || !list) { free(lut); return; }\n"; *(const char * *)tb_grow(v_lines) = tb_v8406; }
    { const char * tb_v8407 = "    for (int k = 0; k < 3; k++) { tb_imgs[n0 + k].w = tb_gw; tb_imgs[n0 + k].h = tb_gh; tb_imgs[n0 + k].off = (uint32_t)(p0 + k * n); }\n"; *(const char * *)tb_grow(v_lines) = tb_v8407; }
    { const char * tb_v8408 = "    tb_nimg = n0 + 3; tb_imgpx_n = need;\n"; *(const char * *)tb_grow(v_lines) = tb_v8408; }
    { const char * tb_v8409 = "    uint32_t *keep = tb_imgpx + p0 + 2 * n;   // кадр процессора: вернуть его видеокарте после пробы\n"; *(const char * *)tb_grow(v_lines) = tb_v8409; }
    { const char * tb_v8410 = "    for (size_t q = 0; q < n; q++) keep[q] = 0xFF000000u | tb_px[q];\n"; *(const char * *)tb_grow(v_lines) = tb_v8410; }
    { const char * tb_v8411 = "    tb_gpu_probing = 1;\n"; *(const char * *)tb_grow(v_lines) = tb_v8411; }
    { const char * tb_v8412 = "    int ok = 1;\n"; *(const char * *)tb_grow(v_lines) = tb_v8412; }
    { const char * tb_v8413 = "    for (size_t from = 0; from < ((size_t)1 << 24) && ok; from += n) {\n"; *(const char * *)tb_grow(v_lines) = tb_v8413; }
    { const char * tb_v8414 = "        uint32_t *bg = tb_imgpx + p0, *fg = bg + n;\n"; *(const char * *)tb_grow(v_lines) = tb_v8414; }
    { const char * tb_v8415 = "        for (size_t q = 0; q < n; q++) {\n"; *(const char * *)tb_grow(v_lines) = tb_v8415; }
    { const char * tb_v8416 = "            size_t i = (from + q) & 0xFFFFFF;\n"; *(const char * *)tb_grow(v_lines) = tb_v8416; }
    { const char * tb_v8417 = "            uint32_t c = (uint32_t)(i >> 16), d = (uint32_t)(i >> 8) & 255, a = (uint32_t)i & 255;\n"; *(const char * *)tb_grow(v_lines) = tb_v8417; }
    { const char * tb_v8418 = "            bg[q] = 0xFF000000u | d * 0x010101u;\n"; *(const char * *)tb_grow(v_lines) = tb_v8418; }
    { const char * tb_v8419 = "            fg[q] = (a << 24) | c * 0x010101u;\n"; *(const char * *)tb_grow(v_lines) = tb_v8419; }
    { const char * tb_v8420 = "        }\n"; *(const char * *)tb_grow(v_lines) = tb_v8420; }
    { const char * tb_v8421 = "        tb_img_dirty = 1;\n"; *(const char * *)tb_grow(v_lines) = tb_v8421; }
    { const char * tb_v8422 = "        tb_gpu_image(n0, 0, 0);\n"; *(const char * *)tb_grow(v_lines) = tb_v8422; }
    { const char * tb_v8423 = "        tb_gpu_image_a(n0 + 1, 0, 0);\n"; *(const char * *)tb_grow(v_lines) = tb_v8423; }
    { const char * tb_v8424 = "        tb_gpu_flush(1);\n"; *(const char * *)tb_grow(v_lines) = tb_v8424; }
    { const char * tb_v8425 = "        if (!tb_gpu_back) { ok = 0; break; }\n"; *(const char * *)tb_grow(v_lines) = tb_v8425; }
    { const char * tb_v8426 = "        for (size_t q = 0; q < n && from + q < ((size_t)1 << 24); q++) lut[from + q] = (uint8_t)(tb_gpu_back[q] & 255);\n"; *(const char * *)tb_grow(v_lines) = tb_v8426; }
    { const char * tb_v8427 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v8427; }
    { const char * tb_v8428 = "    tb_gpu_image(n0 + 2, 0, 0);\n"; *(const char * *)tb_grow(v_lines) = tb_v8428; }
    { const char * tb_v8429 = "    tb_gpu_flush(1);\n"; *(const char * *)tb_grow(v_lines) = tb_v8429; }
    { const char * tb_v8430 = "    tb_gpu_probing = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v8430; }
    { const char * tb_v8431 = "    tb_nimg = n0; tb_imgpx_n = p0; tb_img_dirty = 1;\n"; *(const char * *)tb_grow(v_lines) = tb_v8431; }
    { const char * tb_v8432 = "    if (!ok) { free(lut); return; }\n"; *(const char * *)tb_grow(v_lines) = tb_v8432; }
    { const char * tb_v8433 = "    tb_blend_lut = lut;\n"; *(const char * *)tb_grow(v_lines) = tb_v8433; }
    { const char * tb_v8434 = "    tb_blend_cal = 1;\n"; *(const char * *)tb_grow(v_lines) = tb_v8434; }
    { const char * tb_v8435 = "    const char *e = getenv(\"TB_GPU_INFO\");\n"; *(const char * *)tb_grow(v_lines) = tb_v8435; }
    { const char * tb_v8436 = "    if (e && e[0] == '1') {\n"; *(const char * *)tb_grow(v_lines) = tb_v8436; }
    { const char * tb_v8437 = "        long long diff = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v8437; }
    { const char * tb_v8438 = "        for (size_t i = 0; i < ((size_t)1 << 24); i++) {\n"; *(const char * *)tb_grow(v_lines) = tb_v8438; }
    { const char * tb_v8439 = "            uint32_t c = (uint32_t)(i >> 16), d = (uint32_t)(i >> 8) & 255, a = (uint32_t)i & 255;\n"; *(const char * *)tb_grow(v_lines) = tb_v8439; }
    { const char * tb_v8440 = "            uint32_t w = a == 0 ? d : (c * a + 127) / 255 + (d * (255 - a) + 127) / 255;\n"; *(const char * *)tb_grow(v_lines) = tb_v8440; }
    { const char * tb_v8441 = "            diff += lut[i] != w;\n"; *(const char * *)tb_grow(v_lines) = tb_v8441; }
    { const char * tb_v8442 = "        }\n"; *(const char * *)tb_grow(v_lines) = tb_v8442; }
    { const char * tb_v8443 = "        fprintf(stderr, \"TB_GPU_CHECK: смешивание на этой видеокарте не как округление к ближайшему: %lld из %d\\n\", diff, 1 << 24);\n"; *(const char * *)tb_grow(v_lines) = tb_v8443; }
    { const char * tb_v8444 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v8444; }
    { const char * tb_v8445 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v8445; }
    { const char * tb_v8446 = "// window_sharp(): окно в настоящих точках экрана (Retina, 150% и 200% на Windows). Размер в window_open\n"; *(const char * *)tb_grow(v_lines) = tb_v8446; }
    { const char * tb_v8447 = "// остаётся в «обычных» точках, а кадр, window_w/h и мышь — в настоящих; window_scale() — во сколько раз\n"; *(const char * *)tb_grow(v_lines) = tb_v8447; }
    { const char * tb_v8448 = "TB_API double tb_gfx_scale(void);   // своя у каждой системы\n"; *(const char * *)tb_grow(v_lines) = tb_v8448; }
    { const char * tb_v8449 = "TB_API void tb_window_sharp(void) { if (!tb_px) tb_sharp = 1; }\n"; *(const char * *)tb_grow(v_lines) = tb_v8449; }
    { const char * tb_v8450 = "TB_API double tb_window_scale(void) { return tb_sc; }\n"; *(const char * *)tb_grow(v_lines) = tb_v8450; }
    { const char * tb_v8451 = "TB_API void tb_window_open(long long w, long long h, const char *title) {\n"; *(const char * *)tb_grow(v_lines) = tb_v8451; }
    { const char * tb_v8452 = "    if (tb_px) { tb_err = \"окно уже открыто\"; return; }\n"; *(const char * *)tb_grow(v_lines) = tb_v8452; }
    { const char * tb_v8453 = "    if (w < 1 || h < 1 || w > 8192 || h > 8192) { tb_err = \"размер окна от 1 до 8192\"; return; }\n"; *(const char * *)tb_grow(v_lines) = tb_v8453; }
    { const char * tb_v8454 = "    if (tb_sharp) {\n"; *(const char * *)tb_grow(v_lines) = tb_v8454; }
    { const char * tb_v8455 = "        tb_sc = tb_gfx_scale();\n"; *(const char * *)tb_grow(v_lines) = tb_v8455; }
    { const char * tb_v8456 = "        if (tb_sc < 1) tb_sc = 1;\n"; *(const char * *)tb_grow(v_lines) = tb_v8456; }
    { const char * tb_v8457 = "        if (tb_sc > 4) tb_sc = 4;\n"; *(const char * *)tb_grow(v_lines) = tb_v8457; }
    { const char * tb_v8458 = "        w = (long long)(w * tb_sc + 0.5); h = (long long)(h * tb_sc + 0.5);\n"; *(const char * *)tb_grow(v_lines) = tb_v8458; }
    { const char * tb_v8459 = "        if (w > 8192) w = 8192;\n"; *(const char * *)tb_grow(v_lines) = tb_v8459; }
    { const char * tb_v8460 = "        if (h > 8192) h = 8192;\n"; *(const char * *)tb_grow(v_lines) = tb_v8460; }
    { const char * tb_v8461 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v8461; }
    { const char * tb_v8462 = "    tb_gw = (int)w; tb_gh = (int)h;\n"; *(const char * *)tb_grow(v_lines) = tb_v8462; }
