    { const char * tb_v8485 = "// частота кадров: -1 — как у экрана (по умолчанию), 0 — сколько успеет, n — n кадров в секунду (set_fps)\n"; *(const char * *)tb_grow(v_lines) = tb_v8485; }
    { const char * tb_v8486 = "TB_API double tb_frame_ms_v = 16.0;\n"; *(const char * *)tb_grow(v_lines) = tb_v8486; }
    { const char * tb_v8487 = "TB_API long long tb_fps_want = -1, tb_fps_v = 0, tb_fps_n = 0, tb_fps_t0 = 0, tb_last_us = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v8487; }
    { const char * tb_v8488 = "TB_API void tb_set_fps(long long n) {\n"; *(const char * *)tb_grow(v_lines) = tb_v8488; }
    { const char * tb_v8489 = "    if (n < 0) n = -1;\n"; *(const char * *)tb_grow(v_lines) = tb_v8489; }
    { const char * tb_v8490 = "    tb_fps_want = n;\n"; *(const char * *)tb_grow(v_lines) = tb_v8490; }
    { const char * tb_v8491 = "    int nosync = n == 0 || getenv(\"TB_FPS_FREE\") != 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v8491; }
    { const char * tb_v8492 = "    if (nosync != tb_gpu_nosync) { tb_gpu_nosync = nosync; if (tb_gpu_on) tb_gpu_vsync(); }\n"; *(const char * *)tb_grow(v_lines) = tb_v8492; }
    { const char * tb_v8493 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v8493; }
    { const char * tb_v8494 = "TB_API double tb_frame_ms(void) { return tb_frame_ms_v; }\n"; *(const char * *)tb_grow(v_lines) = tb_v8494; }
    { const char * tb_v8495 = "TB_API long long tb_fps(void) { return tb_fps_v ? tb_fps_v : tb_frame_ms_v > 0 ? (long long)(1000 / tb_frame_ms_v) : 0; }\n"; *(const char * *)tb_grow(v_lines) = tb_v8495; }
    { const char * tb_v8496 = "// показать кадр, принять клавиши и мышь, держать частоту кадров; false — окно закрыли\n"; *(const char * *)tb_grow(v_lines) = tb_v8496; }
    { const char * tb_v8497 = "TB_API int tb_window_alive(void) {\n"; *(const char * *)tb_grow(v_lines) = tb_v8497; }
    { const char * tb_v8498 = "    if (!tb_px || tb_gclosed) return 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v8498; }
    { const char * tb_v8499 = "    tb_gfx_events();   // здесь показывается прошлый кадр\n"; *(const char * *)tb_grow(v_lines) = tb_v8499; }
    { const char * tb_v8500 = "    tb_zclr = tb_gzclr = 1;   // новый кадр: глубина 3D начинается заново\n"; *(const char * *)tb_grow(v_lines) = tb_v8500; }
    { const char * tb_v8501 = "    tb_apply_resize();\n"; *(const char * *)tb_grow(v_lines) = tb_v8501; }
    { const char * tb_v8502 = "    // TB_FPS_FREE=1 — без ограничения (для замеров скорости), как set_fps(0)\n"; *(const char * *)tb_grow(v_lines) = tb_v8502; }
    { const char * tb_v8503 = "    static int free_fps = -1;\n"; *(const char * *)tb_grow(v_lines) = tb_v8503; }
    { const char * tb_v8504 = "    if (free_fps < 0) free_fps = getenv(\"TB_FPS_FREE\") != 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v8504; }
    { const char * tb_v8505 = "    long long now = tb_time_us(), period = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v8505; }
    { const char * tb_v8506 = "    if (!tb_last_us) tb_last_us = now;\n"; *(const char * *)tb_grow(v_lines) = tb_v8506; }
    { const char * tb_v8507 = "    if (free_fps || tb_fps_want == 0) period = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v8507; }
    { const char * tb_v8508 = "    else if (tb_fps_want > 0) period = 1000000 / tb_fps_want;\n"; *(const char * *)tb_grow(v_lines) = tb_v8508; }
    { const char * tb_v8509 = "    // как у экрана: видеокарта сама ждёт обновления экрана (60 Гц — 60 кадров, 120 Гц — 120);\n"; *(const char * *)tb_grow(v_lines) = tb_v8509; }
    { const char * tb_v8510 = "    // кадр пришёл быстрее 4 мс — экран частоту не держит, держим сами 60 кадров в секунду\n"; *(const char * *)tb_grow(v_lines) = tb_v8510; }
    { const char * tb_v8511 = "    else if (!tb_gpu_on || now - tb_last_us < 4000) period = 16667;\n"; *(const char * *)tb_grow(v_lines) = tb_v8511; }
    { const char * tb_v8512 = "    if (period && now - tb_last_us < period) { usleep((useconds_t)(period - (now - tb_last_us))); now = tb_time_us(); }\n"; *(const char * *)tb_grow(v_lines) = tb_v8512; }
    { const char * tb_v8513 = "    tb_frame_ms_v = (now - tb_last_us) / 1000.0;\n"; *(const char * *)tb_grow(v_lines) = tb_v8513; }
    { const char * tb_v8514 = "    tb_last_us = now;\n"; *(const char * *)tb_grow(v_lines) = tb_v8514; }
