    { const char * tb_v8516 = "    tb_fps_n++;\n"; *(const char * *)tb_grow(v_lines) = tb_v8516; }
    { const char * tb_v8517 = "    if (now - tb_fps_t0 >= 1000000) { tb_fps_v = tb_fps_n * 1000000 / (now - tb_fps_t0); tb_fps_n = 0; tb_fps_t0 = now; }\n"; *(const char * *)tb_grow(v_lines) = tb_v8517; }
    { const char * tb_v8518 = "    tb_last_frame = now / 1000;\n"; *(const char * *)tb_grow(v_lines) = tb_v8518; }
    { const char * tb_v8519 = "    return !tb_gclosed;\n"; *(const char * *)tb_grow(v_lines) = tb_v8519; }
    { const char * tb_v8520 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v8520; }
    { const char * tb_v8521 = "TB_INL void tb_put(long long x, long long y, long long c) {\n"; *(const char * *)tb_grow(v_lines) = tb_v8521; }
    { const char * tb_v8522 = "    if (tb_px && x >= 0 && y >= 0 && x < tb_gw && y < tb_gh) tb_px[y * tb_gw + x] = (uint32_t)c;\n"; *(const char * *)tb_grow(v_lines) = tb_v8522; }
    { const char * tb_v8523 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v8523; }
    { const char * tb_v8524 = "// на видеокарте фигуры записываются (tb_gpu_*), на процессоре — рисуются сразу в tb_px.\n"; *(const char * *)tb_grow(v_lines) = tb_v8524; }
    { const char * tb_v8525 = "// TB_GPU_CHECK=1: и то и другое, кадры сверяются\n"; *(const char * *)tb_grow(v_lines) = tb_v8525; }
    { const char * tb_v8526 = "#define TB_CPU_DRAW (!tb_gpu_on || tb_gpu_check)\n"; *(const char * *)tb_grow(v_lines) = tb_v8526; }
    { const char * tb_v8527 = "TB_API void tb_clear_window(long long c) {\n"; *(const char * *)tb_grow(v_lines) = tb_v8527; }
    { const char * tb_v8528 = "    if (!tb_px) return;\n"; *(const char * *)tb_grow(v_lines) = tb_v8528; }
    { const char * tb_v8529 = "    if (tb_gpu_on) { tb_gin = 0; tb_gpu_rect(0, 0, tb_gw, tb_gh, c); }   // всё прежнее закрашено\n"; *(const char * *)tb_grow(v_lines) = tb_v8529; }
    { const char * tb_v8530 = "    if (TB_CPU_DRAW) for (long long i = 0; i < (long long)tb_gw * tb_gh; i++) tb_px[i] = (uint32_t)c;\n"; *(const char * *)tb_grow(v_lines) = tb_v8530; }
    { const char * tb_v8531 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v8531; }
    { const char * tb_v8532 = "TB_API void tb_draw_pixel(long long x, long long y, long long c) {\n"; *(const char * *)tb_grow(v_lines) = tb_v8532; }
    { const char * tb_v8533 = "    if (!tb_px) return;\n"; *(const char * *)tb_grow(v_lines) = tb_v8533; }
    { const char * tb_v8534 = "    if (tb_gpu_on) tb_gpu_rect(x, y, 1, 1, c);\n"; *(const char * *)tb_grow(v_lines) = tb_v8534; }
    { const char * tb_v8535 = "    if (TB_CPU_DRAW) tb_put(x, y, c);\n"; *(const char * *)tb_grow(v_lines) = tb_v8535; }
    { const char * tb_v8536 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v8536; }
    { const char * tb_v8537 = "// полупрозрачный цвет (rgba): в старшем байте — прозрачность 1..255 (0 — непрозрачный, как у rgb)\n"; *(const char * *)tb_grow(v_lines) = tb_v8537; }
    { const char * tb_v8538 = "TB_INL uint32_t tb_mix(uint32_t d, uint32_t c) {\n"; *(const char * *)tb_grow(v_lines) = tb_v8538; }
    { const char * tb_v8539 = "    uint32_t t = (c >> 24) & 255, a = 255 - t;\n"; *(const char * *)tb_grow(v_lines) = tb_v8539; }
    { const char * tb_v8540 = "    uint32_t rb = ((c & 0xFF00FF) * a + (d & 0xFF00FF) * t + 0x800080) >> 8 & 0xFF00FF;\n"; *(const char * *)tb_grow(v_lines) = tb_v8540; }
    { const char * tb_v8541 = "    uint32_t g = ((c & 0x00FF00) * a + (d & 0x00FF00) * t + 0x008000) >> 8 & 0x00FF00;\n"; *(const char * *)tb_grow(v_lines) = tb_v8541; }
    { const char * tb_v8542 = "    return rb | g;\n"; *(const char * *)tb_grow(v_lines) = tb_v8542; }
    { const char * tb_v8543 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v8543; }
    { const char * tb_v8544 = "TB_API void tb_cpu_rect(long long x, long long y, long long w, long long h, long long c) {\n"; *(const char * *)tb_grow(v_lines) = tb_v8544; }
    { const char * tb_v8545 = "    long long x0 = x < 0 ? 0 : x, y0 = y < 0 ? 0 : y, x1 = x + w > tb_gw ? tb_gw : x + w, y1 = y + h > tb_gh ? tb_gh : y + h;\n"; *(const char * *)tb_grow(v_lines) = tb_v8545; }
    { const char * tb_v8546 = "    if ((c >> 24) & 255) {\n"; *(const char * *)tb_grow(v_lines) = tb_v8546; }
    { const char * tb_v8547 = "        for (long long j = y0; j < y1; j++) for (long long i = x0; i < x1; i++) tb_px[j * tb_gw + i] = tb_mix(tb_px[j * tb_gw + i], (uint32_t)c);\n"; *(const char * *)tb_grow(v_lines) = tb_v8547; }
    { const char * tb_v8548 = "        return;\n"; *(const char * *)tb_grow(v_lines) = tb_v8548; }
    { const char * tb_v8549 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v8549; }
    { const char * tb_v8550 = "    for (long long j = y0; j < y1; j++) for (long long i = x0; i < x1; i++) tb_px[j * tb_gw + i] = (uint32_t)c;\n"; *(const char * *)tb_grow(v_lines) = tb_v8550; }
    { const char * tb_v8551 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v8551; }
    { const char * tb_v8552 = "TB_API void tb_draw_rect(long long x, long long y, long long w, long long h, long long c) {\n"; *(const char * *)tb_grow(v_lines) = tb_v8552; }
    { const char * tb_v8553 = "    if (!tb_px) return;\n"; *(const char * *)tb_grow(v_lines) = tb_v8553; }
    { const char * tb_v8554 = "    if (tb_gpu_on) tb_gpu_rect(x, y, w, h, c);\n"; *(const char * *)tb_grow(v_lines) = tb_v8554; }
    { const char * tb_v8555 = "    if (TB_CPU_DRAW) tb_cpu_rect(x, y, w, h, c);\n"; *(const char * *)tb_grow(v_lines) = tb_v8555; }
    { const char * tb_v8556 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v8556; }
    { const char * tb_v8557 = "// точка с покрытием cov (0..1): цвет c (может быть rgba) смешивается с тем, что под ним\n"; *(const char * *)tb_grow(v_lines) = tb_v8557; }
    { const char * tb_v8558 = "TB_INL void tb_cover(long long x, long long y, uint32_t c, double cov) {\n"; *(const char * *)tb_grow(v_lines) = tb_v8558; }
    { const char * tb_v8559 = "    if (x < 0 || y < 0 || x >= tb_gw || y >= tb_gh || cov <= 0) return;\n"; *(const char * *)tb_grow(v_lines) = tb_v8559; }
    { const char * tb_v8560 = "    uint32_t a = 255 - ((c >> 24) & 255);\n"; *(const char * *)tb_grow(v_lines) = tb_v8560; }
    { const char * tb_v8561 = "    a = (uint32_t)(a * (cov > 1 ? 1 : cov) + 0.5);\n"; *(const char * *)tb_grow(v_lines) = tb_v8561; }
    { const char * tb_v8562 = "    if (a == 0) return;\n"; *(const char * *)tb_grow(v_lines) = tb_v8562; }
    { const char * tb_v8563 = "    uint32_t *p = &tb_px[y * tb_gw + x];\n"; *(const char * *)tb_grow(v_lines) = tb_v8563; }
    { const char * tb_v8564 = "    *p = a >= 255 ? (c & 0xFFFFFF) : tb_mix(*p, ((255 - a) << 24) | (c & 0xFFFFFF));\n"; *(const char * *)tb_grow(v_lines) = tb_v8564; }
    { const char * tb_v8565 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v8565; }
    { const char * tb_v8566 = "// draw_shadow(x, y, w, h, r, size, c): мягкая тень скруглённого прямоугольника — внутри цвет c,\n"; *(const char * *)tb_grow(v_lines) = tb_v8566; }
    { const char * tb_v8567 = "// снаружи к size точкам сходит на нет. Корень считается только у кольца и углов, середина — простое смешивание.\n"; *(const char * *)tb_grow(v_lines) = tb_v8567; }
    { const char * tb_v8568 = "TB_API void tb_draw_shadow(long long x, long long y, long long w, long long h, long long r, long long size, long long c) {\n"; *(const char * *)tb_grow(v_lines) = tb_v8568; }
    { const char * tb_v8569 = "    if (!tb_px || w <= 0 || h <= 0 || size <= 0) return;\n"; *(const char * *)tb_grow(v_lines) = tb_v8569; }
    { const char * tb_v8570 = "    if (r * 2 > w) r = w / 2;\n"; *(const char * *)tb_grow(v_lines) = tb_v8570; }
    { const char * tb_v8571 = "    if (r * 2 > h) r = h / 2;\n"; *(const char * *)tb_grow(v_lines) = tb_v8571; }
    { const char * tb_v8572 = "    if (tb_gpu_on) {                                   // видеокарта: слоями (без сглаживания)\n"; *(const char * *)tb_grow(v_lines) = tb_v8572; }
    { const char * tb_v8573 = "        for (long long k = size; k > 0; k -= 2) {\n"; *(const char * *)tb_grow(v_lines) = tb_v8573; }
    { const char * tb_v8574 = "            double f = 1.0 - (double)k / size;\n"; *(const char * *)tb_grow(v_lines) = tb_v8574; }
    { const char * tb_v8575 = "            long long a = (long long)((255 - ((c >> 24) & 255)) * f * f / (size / 2.0) + 0.5);\n"; *(const char * *)tb_grow(v_lines) = tb_v8575; }
    { const char * tb_v8576 = "            if (a > 0) tb_gpu_rect(x - k, y - k + r, w + 2 * k, h + 2 * k - 2 * r, ((255 - a) << 24) | (c & 0xFFFFFF));\n"; *(const char * *)tb_grow(v_lines) = tb_v8576; }
    { const char * tb_v8577 = "        }\n"; *(const char * *)tb_grow(v_lines) = tb_v8577; }
    { const char * tb_v8578 = "        if (!TB_CPU_DRAW) return;\n"; *(const char * *)tb_grow(v_lines) = tb_v8578; }
    { const char * tb_v8579 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v8579; }
    { const char * tb_v8580 = "    double hw = w / 2.0, hh = h / 2.0, cx = x + hw, cy = y + hh;\n"; *(const char * *)tb_grow(v_lines) = tb_v8580; }
    { const char * tb_v8581 = "    long long y0 = y - size < 0 ? 0 : y - size, y1 = y + h + size > tb_gh ? tb_gh : y + h + size;\n"; *(const char * *)tb_grow(v_lines) = tb_v8581; }
    { const char * tb_v8582 = "    for (long long j = y0; j < y1; j++) {\n"; *(const char * *)tb_grow(v_lines) = tb_v8582; }
    { const char * tb_v8583 = "        double py = j + 0.5, dy = fabs(py - cy) - (hh - r);\n"; *(const char * *)tb_grow(v_lines) = tb_v8583; }
    { const char * tb_v8584 = "        if (dy < 0) dy = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v8584; }
    { const char * tb_v8585 = "        long long xa = x - size < 0 ? 0 : x - size, xb = x + w + size > tb_gw ? tb_gw : x + w + size;\n"; *(const char * *)tb_grow(v_lines) = tb_v8585; }
    { const char * tb_v8586 = "        for (long long i = xa; i < xb; i++) {\n"; *(const char * *)tb_grow(v_lines) = tb_v8586; }
    { const char * tb_v8587 = "            double px = i + 0.5, dx = fabs(px - cx) - (hw - r);\n"; *(const char * *)tb_grow(v_lines) = tb_v8587; }
    { const char * tb_v8588 = "            if (dx < 0) dx = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v8588; }
    { const char * tb_v8589 = "            if (dx == 0 && dy == 0) { tb_px[j * tb_gw + i] = tb_mix(tb_px[j * tb_gw + i], (uint32_t)c); continue; }\n"; *(const char * *)tb_grow(v_lines) = tb_v8589; }
    { const char * tb_v8590 = "            double d = sqrt(dx * dx + dy * dy) - r;\n"; *(const char * *)tb_grow(v_lines) = tb_v8590; }
