    { const char * tb_v8597 = "// скругление углов: \"\" или \"all\" — все; иначе слова top bottom left right tl tr bl br через пробел\n"; *(const char * *)tb_grow(v_lines) = tb_v8597; }
    { const char * tb_v8598 = "TB_API int tb_corners(const char *s) {\n"; *(const char * *)tb_grow(v_lines) = tb_v8598; }
    { const char * tb_v8599 = "    if (!s || !*s) return 15;\n"; *(const char * *)tb_grow(v_lines) = tb_v8599; }
    { const char * tb_v8600 = "    int m = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v8600; }
    { const char * tb_v8601 = "    const char *w[] = { \"all\", \"top\", \"bottom\", \"left\", \"right\", \"tl\", \"tr\", \"bl\", \"br\" };\n"; *(const char * *)tb_grow(v_lines) = tb_v8601; }
    { const char * tb_v8602 = "    const int v[] = { 15, 3, 12, 5, 10, 1, 2, 4, 8 };\n"; *(const char * *)tb_grow(v_lines) = tb_v8602; }
    { const char * tb_v8603 = "    while (*s) {\n"; *(const char * *)tb_grow(v_lines) = tb_v8603; }
    { const char * tb_v8604 = "        while (*s == ' ' || *s == ',') s++;\n"; *(const char * *)tb_grow(v_lines) = tb_v8604; }
    { const char * tb_v8605 = "        const char *e = s;\n"; *(const char * *)tb_grow(v_lines) = tb_v8605; }
