    { const char * tb_v8620 = "    if (tb_gpu_on) {   // видеокарта: пока без сглаживания\n"; *(const char * *)tb_grow(v_lines) = tb_v8620; }
    { const char * tb_v8621 = "        tb_gpu_rect(x + r, y, w - 2 * r, h, c); tb_gpu_rect(x, y + r, r, h - 2 * r, c); tb_gpu_rect(x + w - r, y + r, r, h - 2 * r, c);\n"; *(const char * *)tb_grow(v_lines) = tb_v8621; }
    { const char * tb_v8622 = "        tb_gpu_circle(x + r, y + r, r, c); tb_gpu_circle(x + w - 1 - r, y + r, r, c);\n"; *(const char * *)tb_grow(v_lines) = tb_v8622; }
    { const char * tb_v8623 = "        tb_gpu_circle(x + r, y + h - 1 - r, r, c); tb_gpu_circle(x + w - 1 - r, y + h - 1 - r, r, c);\n"; *(const char * *)tb_grow(v_lines) = tb_v8623; }
    { const char * tb_v8624 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v8624; }
    { const char * tb_v8625 = "    if (!TB_CPU_DRAW) return;\n"; *(const char * *)tb_grow(v_lines) = tb_v8625; }
    { const char * tb_v8626 = "    uint32_t cc = (uint32_t)c;\n"; *(const char * *)tb_grow(v_lines) = tb_v8626; }
    { const char * tb_v8627 = "    long long y0 = y < 0 ? 0 : y, y1 = y + h > tb_gh ? tb_gh : y + h;\n"; *(const char * *)tb_grow(v_lines) = tb_v8627; }
    { const char * tb_v8628 = "    for (long long j = y0; j < y1; j++) {\n"; *(const char * *)tb_grow(v_lines) = tb_v8628; }
