    { const char * tb_v8636 = "        if (b > tb_gw) b = tb_gw;\n"; *(const char * *)tb_grow(v_lines) = tb_v8636; }
    { const char * tb_v8637 = "        if ((cc >> 24) & 255) { for (long long i = a; i < b; i++) tb_px[j * tb_gw + i] = tb_mix(tb_px[j * tb_gw + i], cc); }\n"; *(const char * *)tb_grow(v_lines) = tb_v8637; }
    { const char * tb_v8638 = "        else for (long long i = a; i < b; i++) tb_px[j * tb_gw + i] = cc & 0xFFFFFF;\n"; *(const char * *)tb_grow(v_lines) = tb_v8638; }
    { const char * tb_v8639 = "        // углы: покрытие точки по расстоянию до центра угла\n"; *(const char * *)tb_grow(v_lines) = tb_v8639; }
    { const char * tb_v8640 = "        for (int side = 0; side < 2; side++) {\n"; *(const char * *)tb_grow(v_lines) = tb_v8640; }
