    { const char * tb_v8678 = "    int half = r >= 4 && W >= 8 && H >= 8;\n"; *(const char * *)tb_grow(v_lines) = tb_v8678; }
    { const char * tb_v8679 = "    long long bw = half ? (W + 1) / 2 : W, bh = half ? (H + 1) / 2 : H, br = half ? r / 2 : r;\n"; *(const char * *)tb_grow(v_lines) = tb_v8679; }
    { const char * tb_v8680 = "    uint32_t *b = malloc((size_t)(bw * bh + (bw > bh ? bw : bh)) * 4);\n"; *(const char * *)tb_grow(v_lines) = tb_v8680; }
    { const char * tb_v8681 = "    if (!b) return;\n"; *(const char * *)tb_grow(v_lines) = tb_v8681; }
    { const char * tb_v8682 = "    uint32_t *tmp = b + bw * bh;\n"; *(const char * *)tb_grow(v_lines) = tb_v8682; }
    { const char * tb_v8683 = "    if (half)\n"; *(const char * *)tb_grow(v_lines) = tb_v8683; }
    { const char * tb_v8684 = "        for (long long yy = 0; yy < bh; yy++)\n"; *(const char * *)tb_grow(v_lines) = tb_v8684; }
    { const char * tb_v8685 = "            for (long long xx = 0; xx < bw; xx++) {\n"; *(const char * *)tb_grow(v_lines) = tb_v8685; }
    { const char * tb_v8686 = "                long long sx = x0 + xx * 2, sy = y0 + yy * 2, sx2 = sx + 1 < x1 ? sx + 1 : sx, sy2 = sy + 1 < y1 ? sy + 1 : sy;\n"; *(const char * *)tb_grow(v_lines) = tb_v8686; }
    { const char * tb_v8687 = "                uint32_t p = tb_px[sy * tb_gw + sx], q = tb_px[sy * tb_gw + sx2], u = tb_px[sy2 * tb_gw + sx], v = tb_px[sy2 * tb_gw + sx2];\n"; *(const char * *)tb_grow(v_lines) = tb_v8687; }
    { const char * tb_v8688 = "                b[yy * bw + xx] = (((p >> 16 & 255) + (q >> 16 & 255) + (u >> 16 & 255) + (v >> 16 & 255) + 2) / 4) << 16\n"; *(const char * *)tb_grow(v_lines) = tb_v8688; }
    { const char * tb_v8689 = "                    | (((p >> 8 & 255) + (q >> 8 & 255) + (u >> 8 & 255) + (v >> 8 & 255) + 2) / 4) << 8\n"; *(const char * *)tb_grow(v_lines) = tb_v8689; }
    { const char * tb_v8690 = "                    | (((p & 255) + (q & 255) + (u & 255) + (v & 255) + 2) / 4);\n"; *(const char * *)tb_grow(v_lines) = tb_v8690; }
    { const char * tb_v8691 = "            }\n"; *(const char * *)tb_grow(v_lines) = tb_v8691; }
    { const char * tb_v8692 = "    else\n"; *(const char * *)tb_grow(v_lines) = tb_v8692; }
    { const char * tb_v8693 = "        for (long long yy = 0; yy < bh; yy++) memcpy(b + yy * bw, tb_px + (y0 + yy) * tb_gw + x0, (size_t)bw * 4);\n"; *(const char * *)tb_grow(v_lines) = tb_v8693; }
    { const char * tb_v8694 = "    for (int pass = 0; pass < 3; pass++) {\n"; *(const char * *)tb_grow(v_lines) = tb_v8694; }
    { const char * tb_v8695 = "        for (long long yy = 0; yy < bh; yy++) tb_blur_run(b + yy * bw, bw, 1, br, tmp);\n"; *(const char * *)tb_grow(v_lines) = tb_v8695; }
    { const char * tb_v8696 = "        for (long long xx = 0; xx < bw; xx++) tb_blur_run(b + xx, bh, bw, br, tmp);\n"; *(const char * *)tb_grow(v_lines) = tb_v8696; }
    { const char * tb_v8697 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v8697; }
    { const char * tb_v8698 = "    if (half)\n"; *(const char * *)tb_grow(v_lines) = tb_v8698; }
    { const char * tb_v8699 = "        // обратно: каждая точка — смесь четырёх соседних из маленькой картинки\n"; *(const char * *)tb_grow(v_lines) = tb_v8699; }
    { const char * tb_v8700 = "        for (long long yy = 0; yy < H; yy++) {\n"; *(const char * *)tb_grow(v_lines) = tb_v8700; }
    { const char * tb_v8701 = "            long long fy = yy * 128 - 64; if (fy < 0) fy = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v8701; }
    { const char * tb_v8702 = "            long long iy = fy >> 8, ty = fy & 255, iy2 = iy + 1 < bh ? iy + 1 : iy;\n"; *(const char * *)tb_grow(v_lines) = tb_v8702; }
    { const char * tb_v8703 = "            for (long long xx = 0; xx < W; xx++) {\n"; *(const char * *)tb_grow(v_lines) = tb_v8703; }
    { const char * tb_v8704 = "                long long fx = xx * 128 - 64; if (fx < 0) fx = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v8704; }
    { const char * tb_v8705 = "                long long ix = fx >> 8, tx = fx & 255, ix2 = ix + 1 < bw ? ix + 1 : ix;\n"; *(const char * *)tb_grow(v_lines) = tb_v8705; }
    { const char * tb_v8706 = "                uint32_t p = b[iy * bw + ix], q = b[iy * bw + ix2], u = b[iy2 * bw + ix], v = b[iy2 * bw + ix2], o = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v8706; }
    { const char * tb_v8707 = "                for (int sh = 0; sh <= 16; sh += 8) {\n"; *(const char * *)tb_grow(v_lines) = tb_v8707; }
    { const char * tb_v8708 = "                    long long a = (p >> sh & 255) * (256 - tx) + (q >> sh & 255) * tx, c = (u >> sh & 255) * (256 - tx) + (v >> sh & 255) * tx;\n"; *(const char * *)tb_grow(v_lines) = tb_v8708; }
    { const char * tb_v8709 = "                    o |= (uint32_t)(((a * (256 - ty) + c * ty + 32768) >> 16) & 255) << sh;\n"; *(const char * *)tb_grow(v_lines) = tb_v8709; }
    { const char * tb_v8710 = "                }\n"; *(const char * *)tb_grow(v_lines) = tb_v8710; }
    { const char * tb_v8711 = "                tb_px[(y0 + yy) * tb_gw + x0 + xx] = o;\n"; *(const char * *)tb_grow(v_lines) = tb_v8711; }
    { const char * tb_v8712 = "            }\n"; *(const char * *)tb_grow(v_lines) = tb_v8712; }
    { const char * tb_v8713 = "        }\n"; *(const char * *)tb_grow(v_lines) = tb_v8713; }
