    { const char * tb_v8773 = "// без знака (переполнение по кругу), потом сдвиг; 0 — у самой камеры, 16777215 — далеко\n"; *(const char * *)tb_grow(v_lines) = tb_v8773; }
    { const char * tb_v8774 = "TB_INL uint32_t tb_tri3_depth(const uint32_t *pl, long long x, long long y) {\n"; *(const char * *)tb_grow(v_lines) = tb_v8774; }
    { const char * tb_v8775 = "    uint32_t k = pl[2] + pl[0] * (uint32_t)(2 * x + 1) + pl[1] * (uint32_t)(2 * y + 1);\n"; *(const char * *)tb_grow(v_lines) = tb_v8775; }
