    { const char * tb_v8791 = "        }\n"; *(const char * *)tb_grow(v_lines) = tb_v8791; }
    { const char * tb_v8792 = "        if (xa < 0) xa = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v8792; }
    { const char * tb_v8793 = "        if (ya < 0) ya = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v8793; }
    { const char * tb_v8794 = "        if (xb > tb_gw - 1) xb = tb_gw - 1;\n"; *(const char * *)tb_grow(v_lines) = tb_v8794; }
    { const char * tb_v8795 = "        if (yb > tb_gh - 1) yb = tb_gh - 1;\n"; *(const char * *)tb_grow(v_lines) = tb_v8795; }
