    { const char * tb_v8808 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v8808; }
    { const char * tb_v8809 = "static void tb_tri_draw_i(long long *t, long long c, const uint32_t *pl) { tb_tri_draw_x(t, c, pl, tb_gpu_on, TB_CPU_DRAW); }\n"; *(const char * *)tb_grow(v_lines) = tb_v8809; }
    { const char * tb_v8810 = "// многоугольник с углами-дробями (3D после проекции, огромные треугольники): обрезаем рамкой\n"; *(const char * *)tb_grow(v_lines) = tb_v8810; }
    { const char * tb_v8811 = "// вокруг окна (±2048 точек, но не дальше ±8192), углы округляем, режем веером из первого угла.\n"; *(const char * *)tb_grow(v_lines) = tb_v8811; }
    { const char * tb_v8812 = "// Общие углы округляются одинаково, поэтому соседние треугольники стыкуются без щелей\n"; *(const char * *)tb_grow(v_lines) = tb_v8812; }
    { const char * tb_v8813 = "// округление до ближайшего целого (половина — вверх); быстрее llround, одно и то же везде\n"; *(const char * *)tb_grow(v_lines) = tb_v8813; }
    { const char * tb_v8814 = "TB_INL long long tb_rnd(double x) {\n"; *(const char * *)tb_grow(v_lines) = tb_v8814; }
    { const char * tb_v8815 = "    long long r = (long long)(x + 0.5);\n"; *(const char * *)tb_grow(v_lines) = tb_v8815; }
    { const char * tb_v8816 = "    if ((double)r > x + 0.5) r--;\n"; *(const char * *)tb_grow(v_lines) = tb_v8816; }
    { const char * tb_v8817 = "    return r;\n"; *(const char * *)tb_grow(v_lines) = tb_v8817; }
    { const char * tb_v8818 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v8818; }
    { const char * tb_v8819 = "static void tb_poly_draw(double *px, double *py, int n, long long c, const uint32_t *pl) {\n"; *(const char * *)tb_grow(v_lines) = tb_v8819; }
    { const char * tb_v8820 = "    double gx0 = -2048, gy0 = -2048, gx1 = tb_gw + 2048.0, gy1 = tb_gh + 2048.0;\n"; *(const char * *)tb_grow(v_lines) = tb_v8820; }
    { const char * tb_v8821 = "    if (gx1 > 8192) gx1 = 8192;\n"; *(const char * *)tb_grow(v_lines) = tb_v8821; }
    { const char * tb_v8822 = "    if (gy1 > 8192) gy1 = 8192;\n"; *(const char * *)tb_grow(v_lines) = tb_v8822; }
    { const char * tb_v8823 = "    double ax[16], ay[16], bx[16], by[16];\n"; *(const char * *)tb_grow(v_lines) = tb_v8823; }
    { const char * tb_v8824 = "    for (int i = 0; i < n; i++) { ax[i] = px[i]; ay[i] = py[i]; }\n"; *(const char * *)tb_grow(v_lines) = tb_v8824; }
    { const char * tb_v8825 = "    for (int side = 0; side < 4 && n > 0; side++) {   // Сазерленд — Ходжман: по одной стороне рамки\n"; *(const char * *)tb_grow(v_lines) = tb_v8825; }
    { const char * tb_v8826 = "        int m = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v8826; }
    { const char * tb_v8827 = "        for (int i = 0; i < n; i++) {\n"; *(const char * *)tb_grow(v_lines) = tb_v8827; }
    { const char * tb_v8828 = "            int j = (i + 1) % n;\n"; *(const char * *)tb_grow(v_lines) = tb_v8828; }
    { const char * tb_v8829 = "            double vi = side == 0 ? ax[i] - gx0 : side == 1 ? gx1 - ax[i] : side == 2 ? ay[i] - gy0 : gy1 - ay[i];\n"; *(const char * *)tb_grow(v_lines) = tb_v8829; }
    { const char * tb_v8830 = "            double vj = side == 0 ? ax[j] - gx0 : side == 1 ? gx1 - ax[j] : side == 2 ? ay[j] - gy0 : gy1 - ay[j];\n"; *(const char * *)tb_grow(v_lines) = tb_v8830; }
    { const char * tb_v8831 = "            if (vi >= 0) { bx[m] = ax[i]; by[m] = ay[i]; m++; }\n"; *(const char * *)tb_grow(v_lines) = tb_v8831; }
    { const char * tb_v8832 = "            if ((vi >= 0) != (vj >= 0)) {\n"; *(const char * *)tb_grow(v_lines) = tb_v8832; }
    { const char * tb_v8833 = "                double k = vi / (vi - vj);\n"; *(const char * *)tb_grow(v_lines) = tb_v8833; }
    { const char * tb_v8834 = "                bx[m] = ax[i] + (ax[j] - ax[i]) * k; by[m] = ay[i] + (ay[j] - ay[i]) * k; m++;\n"; *(const char * *)tb_grow(v_lines) = tb_v8834; }
    { const char * tb_v8835 = "            }\n"; *(const char * *)tb_grow(v_lines) = tb_v8835; }
    { const char * tb_v8836 = "        }\n"; *(const char * *)tb_grow(v_lines) = tb_v8836; }
    { const char * tb_v8837 = "        n = m;\n"; *(const char * *)tb_grow(v_lines) = tb_v8837; }
    { const char * tb_v8838 = "        for (int i = 0; i < n; i++) { ax[i] = bx[i]; ay[i] = by[i]; }\n"; *(const char * *)tb_grow(v_lines) = tb_v8838; }
    { const char * tb_v8839 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v8839; }
    { const char * tb_v8840 = "    if (n < 3) return;\n"; *(const char * *)tb_grow(v_lines) = tb_v8840; }
