    { const char * tb_v8842 = "    for (int i = 0; i < n; i++) { rx[i] = tb_rnd(ax[i]); ry[i] = tb_rnd(ay[i]); }\n"; *(const char * *)tb_grow(v_lines) = tb_v8842; }
