    { const char * tb_v8844 = "        long long t[6] = { rx[0], ry[0], rx[i], ry[i], rx[i + 1], ry[i + 1] };\n"; *(const char * *)tb_grow(v_lines) = tb_v8844; }
    { const char * tb_v8845 = "        tb_tri_draw_i(t, c, pl);\n"; *(const char * *)tb_grow(v_lines) = tb_v8845; }
