    { const char * tb_v8847 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v8847; }
    { const char * tb_v8848 = "TB_API void tb_draw_triangle(long long x1, long long y1, long long x2, long long y2, long long x3, long long y3, long long c) {\n"; *(const char * *)tb_grow(v_lines) = tb_v8848; }
    { const char * tb_v8849 = "    if (!tb_px) return;\n"; *(const char * *)tb_grow(v_lines) = tb_v8849; }
