    { const char * tb_v9114 = "                qx[n] = p->cx + (q->cx - p->cx) * k; qy[n] = p->cy + (q->cy - p->cy) * k; qz[n] = zn; n++;\n"; *(const char * *)tb_grow(v_lines) = tb_v9114; }
    { const char * tb_v9115 = "            }\n"; *(const char * *)tb_grow(v_lines) = tb_v9115; }
    { const char * tb_v9116 = "        }\n"; *(const char * *)tb_grow(v_lines) = tb_v9116; }
    { const char * tb_v9117 = "        if (n < 3) continue;\n"; *(const char * *)tb_grow(v_lines) = tb_v9117; }
    { const char * tb_v9118 = "        double sx[4], sy[4], dd[4];\n"; *(const char * *)tb_grow(v_lines) = tb_v9118; }
    { const char * tb_v9119 = "        for (int i = 0; i < n; i++) {\n"; *(const char * *)tb_grow(v_lines) = tb_v9119; }
    { const char * tb_v9120 = "            double iz = 1 / qz[i];\n"; *(const char * *)tb_grow(v_lines) = tb_v9120; }
    { const char * tb_v9121 = "            sx[i] = hw + f * qx[i] * iz;\n"; *(const char * *)tb_grow(v_lines) = tb_v9121; }
    { const char * tb_v9122 = "            sy[i] = hh - f * qy[i] * iz;\n"; *(const char * *)tb_grow(v_lines) = tb_v9122; }
    { const char * tb_v9123 = "            dd[i] = (1 - zn * iz) * 16777216.0;\n"; *(const char * *)tb_grow(v_lines) = tb_v9123; }
    { const char * tb_v9124 = "        }\n"; *(const char * *)tb_grow(v_lines) = tb_v9124; }
    { const char * tb_v9125 = "        if (!tb_tri3_plane(sx, sy, dd, pl)) continue;\n"; *(const char * *)tb_grow(v_lines) = tb_v9125; }
    { const char * tb_v9126 = "        tb_poly_draw(sx, sy, n, m->c[t], pl);\n"; *(const char * *)tb_grow(v_lines) = tb_v9126; }
    { const char * tb_v9127 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v9127; }
    { const char * tb_v9128 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v9128; }
    { const char * tb_v9129 = "// ---- 3D в целых числах: так же считает видеокарта (compiler/gpu/tb3.vert, tb.metal) ----\n"; *(const char * *)tb_grow(v_lines) = tb_v9129; }
    { const char * tb_v9130 = "// деление с округлением вниз (b > 0); через числа без знака — одинаково на любой видеокарте\n"; *(const char * *)tb_grow(v_lines) = tb_v9130; }
    { const char * tb_v9131 = "TB_INL long long tb_fdiv(long long a, long long b) {\n"; *(const char * *)tb_grow(v_lines) = tb_v9131; }
    { const char * tb_v9132 = "    return a >= 0 ? (long long)((unsigned long long)a / (unsigned long long)b)\n"; *(const char * *)tb_grow(v_lines) = tb_v9132; }
    { const char * tb_v9133 = "                  : -(long long)(((unsigned long long)(-a) + (unsigned long long)b - 1) / (unsigned long long)b);\n"; *(const char * *)tb_grow(v_lines) = tb_v9133; }
    { const char * tb_v9134 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v9134; }
    { const char * tb_v9135 = "// фокус экрана × 256 (угол обзора 60°)\n"; *(const char * *)tb_grow(v_lines) = tb_v9135; }
    { const char * tb_v9136 = "TB_INL long long tb_m3_f(void) { return tb_rnd(tb_gh / 2.0 / tan(30 * 3.14159265358979323846 / 180) * 256); }\n"; *(const char * *)tb_grow(v_lines) = tb_v9136; }
    { const char * tb_v9137 = "// угол сетки p (× 4096) по записи r: место на экране (целые точки) и глубина D = 2^24 - 2^24 * zn / z, zn = 205 / 4096\n"; *(const char * *)tb_grow(v_lines) = tb_v9137; }
    { const char * tb_v9138 = "TB_INL void tb_m3_corner(const int32_t *r, const int32_t *p, long long f, long long *o) {\n"; *(const char * *)tb_grow(v_lines) = tb_v9138; }
    { const char * tb_v9139 = "    long long c[3];\n"; *(const char * *)tb_grow(v_lines) = tb_v9139; }
    { const char * tb_v9140 = "    for (int k = 0; k < 3; k++)\n"; *(const char * *)tb_grow(v_lines) = tb_v9140; }
    { const char * tb_v9141 = "        c[k] = (((long long)r[4 * k] * p[0] + (long long)r[4 * k + 1] * p[1] + (long long)r[4 * k + 2] * p[2]) >> 30) + r[4 * k + 3];\n"; *(const char * *)tb_grow(v_lines) = tb_v9141; }
    { const char * tb_v9142 = "    o[0] = ((long long)tb_gw * 128 + tb_fdiv(f * c[0], c[2]) + 128) >> 8;\n"; *(const char * *)tb_grow(v_lines) = tb_v9142; }
    { const char * tb_v9143 = "    o[1] = ((long long)tb_gh * 128 - tb_fdiv(f * c[1], c[2]) + 128) >> 8;\n"; *(const char * *)tb_grow(v_lines) = tb_v9143; }
    { const char * tb_v9144 = "    o[2] = 16777216 - tb_fdiv(205LL << 24, c[2]);\n"; *(const char * *)tb_grow(v_lines) = tb_v9144; }
    { const char * tb_v9145 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v9145; }
    { const char * tb_v9146 = "// треугольник a, b, c (x, y, D): 0 — рисовать нечего (ребром к нам или невидимая грань); иначе углы\n"; *(const char * *)tb_grow(v_lines) = tb_v9146; }
    { const char * tb_v9147 = "// по кругу «как надо» в t и плоскость глубины в pl — то же, что tb_tri3_plane, только в целых\n"; *(const char * *)tb_grow(v_lines) = tb_v9147; }
    { const char * tb_v9148 = "TB_INL int tb_m3_tri(const long long *a, const long long *b, const long long *c, int cull, long long *t, uint32_t *pl) {\n"; *(const char * *)tb_grow(v_lines) = tb_v9148; }
    { const char * tb_v9149 = "    long long area = (b[0] - a[0]) * (c[1] - a[1]) - (b[1] - a[1]) * (c[0] - a[0]);\n"; *(const char * *)tb_grow(v_lines) = tb_v9149; }
    { const char * tb_v9150 = "    if (area == 0 || (cull > 0 && area > 0) || (cull < 0 && area < 0)) return 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v9150; }
    { const char * tb_v9151 = "    if (area < 0) { const long long *k = b; b = c; c = k; area = -area; }\n"; *(const char * *)tb_grow(v_lines) = tb_v9151; }
    { const char * tb_v9152 = "    long long e1x = b[0] - a[0], e1y = b[1] - a[1], e2x = c[0] - a[0], e2y = c[1] - a[1], d1 = b[2] - a[2], d2 = c[2] - a[2];\n"; *(const char * *)tb_grow(v_lines) = tb_v9152; }
    { const char * tb_v9153 = "    long long A = tb_fdiv(64 * (d1 * e2y - d2 * e1y) + area, 2 * area), B = tb_fdiv(64 * (d2 * e1x - d1 * e2x) + area, 2 * area);\n"; *(const char * *)tb_grow(v_lines) = tb_v9153; }
    { const char * tb_v9154 = "    long long C = 64 * a[2] - 2 * A * a[0] - 2 * B * a[1];\n"; *(const char * *)tb_grow(v_lines) = tb_v9154; }
    { const char * tb_v9155 = "    pl[0] = (uint32_t)A; pl[1] = (uint32_t)B; pl[2] = (uint32_t)C;\n"; *(const char * *)tb_grow(v_lines) = tb_v9155; }
    { const char * tb_v9156 = "    t[0] = a[0]; t[1] = a[1]; t[2] = b[0]; t[3] = b[1]; t[4] = c[0]; t[5] = c[1];\n"; *(const char * *)tb_grow(v_lines) = tb_v9156; }
    { const char * tb_v9157 = "    return 1;\n"; *(const char * *)tb_grow(v_lines) = tb_v9157; }
    { const char * tb_v9158 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v9158; }
    { const char * tb_v9159 = "// закрытая сетка (каждая сторона треугольника есть и в обратную сторону у соседа): грань, повёрнутая\n"; *(const char * *)tb_grow(v_lines) = tb_v9159; }
    { const char * tb_v9160 = "// от камеры, всегда закрыта другими гранями — и у куба снаружи, и у комнаты изнутри (грани внутрь).\n"; *(const char * *)tb_grow(v_lines) = tb_v9160; }
    { const char * tb_v9161 = "// Повёрнута от камеры = на экране по часовой стрелке (площадь < 0). 0 — рисовать все, -1 — пропускать такие\n"; *(const char * *)tb_grow(v_lines) = tb_v9161; }
    { const char * tb_v9162 = "static int tb_cmp_u64(const void *a, const void *b) {\n"; *(const char * *)tb_grow(v_lines) = tb_v9162; }
    { const char * tb_v9163 = "    uint64_t x = *(const uint64_t *)a, y = *(const uint64_t *)b;\n"; *(const char * *)tb_grow(v_lines) = tb_v9163; }
    { const char * tb_v9164 = "    return x < y ? -1 : x > y;\n"; *(const char * *)tb_grow(v_lines) = tb_v9164; }
    { const char * tb_v9165 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v9165; }
    { const char * tb_v9166 = "static int tb_mesh_cull(tb_mesh *m) {\n"; *(const char * *)tb_grow(v_lines) = tb_v9166; }
    { const char * tb_v9167 = "    if (m->cullok) return m->cull;\n"; *(const char * *)tb_grow(v_lines) = tb_v9167; }
    { const char * tb_v9168 = "    m->cullok = 1; m->cull = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v9168; }
    { const char * tb_v9169 = "    long long ne = 3 * m->n;\n"; *(const char * *)tb_grow(v_lines) = tb_v9169; }
    { const char * tb_v9170 = "    uint64_t *e = (uint64_t *)malloc(sizeof(uint64_t) * (size_t)(ne ? ne : 1));\n"; *(const char * *)tb_grow(v_lines) = tb_v9170; }
    { const char * tb_v9171 = "    double vol = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v9171; }
    { const char * tb_v9172 = "    for (long long t = 0; t < m->n; t++) {\n"; *(const char * *)tb_grow(v_lines) = tb_v9172; }
    { const char * tb_v9173 = "        const uint32_t *ti = m->t + 3 * t;\n"; *(const char * *)tb_grow(v_lines) = tb_v9173; }
    { const char * tb_v9174 = "        for (int k = 0; k < 3; k++) e[3 * t + k] = ((uint64_t)ti[k] << 32) | ti[(k + 1) % 3];\n"; *(const char * *)tb_grow(v_lines) = tb_v9174; }
    { const char * tb_v9175 = "        const double *p = m->v + 3 * ti[0], *q = m->v + 3 * ti[1], *r = m->v + 3 * ti[2];\n"; *(const char * *)tb_grow(v_lines) = tb_v9175; }
    { const char * tb_v9176 = "        vol += p[0] * (q[1] * r[2] - q[2] * r[1]) + p[1] * (q[2] * r[0] - q[0] * r[2]) + p[2] * (q[0] * r[1] - q[1] * r[0]);\n"; *(const char * *)tb_grow(v_lines) = tb_v9176; }
    { const char * tb_v9177 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v9177; }
    { const char * tb_v9178 = "    qsort(e, (size_t)ne, sizeof(uint64_t), tb_cmp_u64);\n"; *(const char * *)tb_grow(v_lines) = tb_v9178; }
    { const char * tb_v9179 = "    int closed = ne > 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v9179; }
    { const char * tb_v9180 = "    for (long long i = 0; i < ne && closed; i++) {\n"; *(const char * *)tb_grow(v_lines) = tb_v9180; }
    { const char * tb_v9181 = "        if (i + 1 < ne && e[i] == e[i + 1]) closed = 0;   // одна сторона дважды в одну сторону\n"; *(const char * *)tb_grow(v_lines) = tb_v9181; }
    { const char * tb_v9182 = "        uint64_t back = (e[i] << 32) | (e[i] >> 32);\n"; *(const char * *)tb_grow(v_lines) = tb_v9182; }
    { const char * tb_v9183 = "        if ((uint32_t)e[i] == (uint32_t)(e[i] >> 32) || !bsearch(&back, e, (size_t)ne, sizeof(uint64_t), tb_cmp_u64)) closed = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v9183; }
    { const char * tb_v9184 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v9184; }
    { const char * tb_v9185 = "    free(e);\n"; *(const char * *)tb_grow(v_lines) = tb_v9185; }
    { const char * tb_v9186 = "    if (closed && fabs(vol) > 1e-12) m->cull = -1;\n"; *(const char * *)tb_grow(v_lines) = tb_v9186; }
    { const char * tb_v9187 = "    return m->cull;\n"; *(const char * *)tb_grow(v_lines) = tb_v9187; }
    { const char * tb_v9188 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v9188; }
    { const char * tb_v9189 = "// сетки для видеокарты: у каждой сначала углы (x, y, z, 0), потом треугольники (номера углов, цвет)\n"; *(const char * *)tb_grow(v_lines) = tb_v9189; }
    { const char * tb_v9190 = "TB_API long long tb_mesh_pack(int32_t *dst) {\n"; *(const char * *)tb_grow(v_lines) = tb_v9190; }
    { const char * tb_v9191 = "    long long at = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v9191; }
    { const char * tb_v9192 = "    for (long long i = 0; i < tb_nmesh; i++) {\n"; *(const char * *)tb_grow(v_lines) = tb_v9192; }
    { const char * tb_v9193 = "        tb_mesh *m = &tb_meshes[i];\n"; *(const char * *)tb_grow(v_lines) = tb_v9193; }
    { const char * tb_v9194 = "        m->gv = at; m->gt = at + m->nv;\n"; *(const char * *)tb_grow(v_lines) = tb_v9194; }
    { const char * tb_v9195 = "        if (dst) {\n"; *(const char * *)tb_grow(v_lines) = tb_v9195; }
    { const char * tb_v9196 = "            memcpy(dst + 4 * at, m->vi, sizeof(int32_t) * 4 * (size_t)m->nv);\n"; *(const char * *)tb_grow(v_lines) = tb_v9196; }
    { const char * tb_v9197 = "            for (long long t = 0; t < m->n; t++) {\n"; *(const char * *)tb_grow(v_lines) = tb_v9197; }
    { const char * tb_v9198 = "                int32_t *o = dst + 4 * (m->gt + t);\n"; *(const char * *)tb_grow(v_lines) = tb_v9198; }
    { const char * tb_v9199 = "                for (int k = 0; k < 3; k++) o[k] = (int32_t)(m->t[3 * t + k] + m->gv);\n"; *(const char * *)tb_grow(v_lines) = tb_v9199; }
    { const char * tb_v9200 = "                o[3] = (int32_t)(m->c[t] & 0xFFFFFF);\n"; *(const char * *)tb_grow(v_lines) = tb_v9200; }
    { const char * tb_v9201 = "            }\n"; *(const char * *)tb_grow(v_lines) = tb_v9201; }
    { const char * tb_v9202 = "        }\n"; *(const char * *)tb_grow(v_lines) = tb_v9202; }
    { const char * tb_v9203 = "        at += m->nv + m->n;\n"; *(const char * *)tb_grow(v_lines) = tb_v9203; }
    { const char * tb_v9204 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v9204; }
    { const char * tb_v9205 = "    return at;\n"; *(const char * *)tb_grow(v_lines) = tb_v9205; }
    { const char * tb_v9206 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v9206; }
    { const char * tb_v9207 = "TB_API void tb_mesh_gpc(const tb_ginst *g, int slot, tb_gpc *pc) {\n"; *(const char * *)tb_grow(v_lines) = tb_v9207; }
    { const char * tb_v9208 = "    tb_mesh *m = &tb_meshes[g->x0];\n"; *(const char * *)tb_grow(v_lines) = tb_v9208; }
    { const char * tb_v9209 = "    pc->size[0] = (float)tb_gw; pc->size[1] = (float)tb_gh;\n"; *(const char * *)tb_grow(v_lines) = tb_v9209; }
    { const char * tb_v9210 = "    pc->tbase = (int32_t)(m->gt + g->ox); pc->ntri = g->oy; pc->rbase = (slot * TB_GR_CAP + g->x1) * 3;\n"; *(const char * *)tb_grow(v_lines) = tb_v9210; }
    { const char * tb_v9211 = "    pc->f = (int32_t)tb_m3_f(); pc->gw = tb_gw; pc->gh = tb_gh; pc->cull = g->y0;\n"; *(const char * *)tb_grow(v_lines) = tb_v9211; }
    { const char * tb_v9212 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v9212; }
    { const char * tb_v9213 = "TB_API long long *tb_3i = 0;   // углы сетки после камеры в целых: x, y, D\n"; *(const char * *)tb_grow(v_lines) = tb_v9213; }
    { const char * tb_v9214 = "TB_API long long tb_3icap = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v9214; }
    { const char * tb_v9215 = "// шар сетки или куска (центр в сетке, радиус) после камеры: 0 — не видно совсем (за камерой или вне экрана\n"; *(const char * *)tb_grow(v_lines) = tb_v9215; }
    { const char * tb_v9216 = "// с запасом 2 точки), 1 — целые годятся (весь перед камерой, на экране не дальше ±8100 точек), 2 — старый путь\n"; *(const char * *)tb_grow(v_lines) = tb_v9216; }
    { const char * tb_v9217 = "static int tb_m3_test(const double *sp, double M[3][3], const double *T, double f, int big) {\n"; *(const char * *)tb_grow(v_lines) = tb_v9217; }
    { const char * tb_v9218 = "    double cc[3], rad = sp[3];\n"; *(const char * *)tb_grow(v_lines) = tb_v9218; }
    { const char * tb_v9219 = "    for (int k = 0; k < 3; k++) cc[k] = M[k][0] * sp[0] + M[k][1] * sp[1] + M[k][2] * sp[2] + T[k];\n"; *(const char * *)tb_grow(v_lines) = tb_v9219; }
    { const char * tb_v9220 = "    if (cc[2] + rad < 205.0 / 4096) return 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v9220; }
    { const char * tb_v9221 = "    double hw = tb_gw / 2.0 + 2, hh = tb_gh / 2.0 + 2, lx = sqrt(f * f + hw * hw), ly = sqrt(f * f + hh * hh);\n"; *(const char * *)tb_grow(v_lines) = tb_v9221; }
    { const char * tb_v9222 = "    if ((f * cc[0] - hw * cc[2]) / lx > rad || (-f * cc[0] - hw * cc[2]) / lx > rad) return 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v9222; }
    { const char * tb_v9223 = "    if ((f * cc[1] - hh * cc[2]) / ly > rad || (-f * cc[1] - hh * cc[2]) / ly > rad) return 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v9223; }
    { const char * tb_v9224 = "    double zmin = cc[2] - rad;\n"; *(const char * *)tb_grow(v_lines) = tb_v9224; }
    { const char * tb_v9225 = "    int ok = !big && zmin >= 0.12 && fabs(T[0]) < 400000 && fabs(T[1]) < 400000 && fabs(T[2]) < 400000 &&\n"; *(const char * *)tb_grow(v_lines) = tb_v9225; }
    { const char * tb_v9226 = "             fabs(cc[0]) + rad < 400000 && fabs(cc[1]) + rad < 400000 && cc[2] + rad < 400000;\n"; *(const char * *)tb_grow(v_lines) = tb_v9226; }
    { const char * tb_v9227 = "    if (ok) ok = tb_gw / 2.0 + f * (fabs(cc[0]) + rad) / zmin < 8100 && tb_gh / 2.0 + f * (fabs(cc[1]) + rad) / zmin < 8100;\n"; *(const char * *)tb_grow(v_lines) = tb_v9227; }
    { const char * tb_v9228 = "    return ok ? 1 : 2;\n"; *(const char * *)tb_grow(v_lines) = tb_v9228; }
    { const char * tb_v9229 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v9229; }
    { const char * tb_v9230 = "// один draw_mesh в целых: запись (одна на вызов, в текущем наборе) и куски треугольников\n"; *(const char * *)tb_grow(v_lines) = tb_v9230; }
    { const char * tb_v9231 = "typedef struct { tb_mesh *m; long long id; int cull; long long ri, rbatch; tb_grec rec; } tb_m3_go;\n"; *(const char * *)tb_grow(v_lines) = tb_v9231; }
    { const char * tb_v9232 = "TB_API long long *tb_3ist = 0, tb_3igen = 0;   // какой угол уже посчитан в этом вызове (процессор)\n"; *(const char * *)tb_grow(v_lines) = tb_v9232; }
    { const char * tb_v9233 = "static void tb_m3_draw(tb_m3_go *go, long long t0, long long tn) {\n"; *(const char * *)tb_grow(v_lines) = tb_v9233; }
    { const char * tb_v9234 = "    tb_mesh *m = go->m;\n"; *(const char * *)tb_grow(v_lines) = tb_v9234; }
    { const char * tb_v9235 = "    if (tb_gpu_on && tb_gpu_mesh) {   // видеокарта считает сама: только запись и «нарисуй треугольники t0.. из сетки»\n"; *(const char * *)tb_grow(v_lines) = tb_v9235; }
    { const char * tb_v9236 = "        if (tb_gin == TB_GI_CAP || (go->rbatch != tb_gbatch && tb_grn == TB_GR_CAP)) tb_gpu_flush(0);\n"; *(const char * *)tb_grow(v_lines) = tb_v9236; }
